/**
 * MongoDB Atlas — clusters, start/stop, schedules, utilization, administration.
 *
 * Every call goes to the portal's backend, which talks to Atlas with the
 * portal's own API key; the browser never sees an Atlas credential. A
 * database-user password generated by the backend is returned once in the
 * mutation result and is deliberately not kept in any React Query cache.
 *
 * Datetimes ending in "Z" are UTC. One-time schedule legs (stop_at /
 * start_at) carry no zone: they are wall-clock times in the schedule's own
 * timezone.
 */

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import apiClient from "./apiClient";

const BASE = "/mongodb-atlas";

// ── Types ────────────────────────────────────────────────────────────────────

export type Environment = "production" | "non_production" | "unclassified";
export type PowerAction = "pause" | "resume";
export type Leg = "stop" | "start";
export type NotifyOn = "always" | "failure" | "never";
export type OperationStatus = "in_progress" | "completed" | "partial" | "failed" | "skipped";
export type TargetStatus = "pending" | "in_progress" | "completed" | "no_change" | "skipped" | "failed";
export type MetricPeriod = "PT1H" | "PT6H" | "PT24H" | "P7D" | "P30D";

export interface AtlasStatus {
  configured: boolean;
  reachable: boolean;
  base_url: string;
  public_key: string | null;
  org_filter: string | null;
  project_allowlist: string[];
  operation_timeout_minutes: number;
  error: string | null;
  error_code?: string | null;
  /** The address Atlas sees the portal calling from — what the API access list must contain. */
  portal_ip: string | null;
  api_key_roles: { scope: "organization" | "project"; id: string; role: string }[];
  project_count: number;
  checked_at: string;
  /** Proxy the backend uses for Atlas (credentials masked), and where it came from. */
  proxy: string | null;
  proxy_source: "MONGODB_ATLAS_PROXY" | "environment" | "none";
}

export interface ConnectionTestStep {
  name: "configuration" | "dns" | "tcp" | "https" | "api_key" | "projects";
  label: string;
  status: "ok" | "failed" | "skipped";
  detail: string;
  ms: number | null;
}

export interface ConnectionTestResult {
  ok: boolean;
  summary: string;
  steps: ConnectionTestStep[];
  proxy: string | null;
  proxy_source: AtlasStatus["proxy_source"];
  checked_at: string;
}

export interface AtlasProject {
  id: string;
  name: string;
  org_id: string;
  cluster_count: number | null;
  created_at: string | null;
}

export interface ClusterScheduleRef {
  id: number;
  name: string;
  is_enabled: boolean;
  next_stop_at: string | null;
  next_start_at: string | null;
}

export interface AtlasCluster {
  id: string;
  name: string;
  project_id: string;
  project_name: string;
  /** IDLE | CREATING | UPDATING | DELETING | REPAIRING */
  state: string | null;
  paused: boolean;
  /** running | paused | updating | creating | … */
  status: string;
  tier: string | null;
  provider: string | null;
  regions: string[];
  cluster_type: string | null;
  mongo_version: string | null;
  mongo_major_version: string | null;
  disk_size_gb: number | null;
  node_count: number;
  shard_count: number;
  backup_enabled: boolean;
  pit_enabled: boolean;
  termination_protection: boolean;
  tags: { key: string; value: string }[];
  connection_string: string | null;
  created_at: string | null;
  autoscaling: {
    compute_enabled: boolean;
    scale_down_enabled: boolean;
    min_tier: string | null;
    max_tier: string | null;
    disk_enabled: boolean;
  };
  pausable: boolean;
  pause_blocker: string | null;
  environment: Environment;
  /** Production or unclassified: a stop needs the name typed again. */
  is_production: boolean;
  // Added by the inventory route
  schedules?: ClusterScheduleRef[];
  paused_since?: string | null;
  paused_days?: number | null;
  auto_resume_warning?: boolean;
  operation_in_progress?: { id: number; action: PowerAction } | null;
}

export interface ClusterInventory {
  clusters: AtlasCluster[];
  errors: { project_id: string; project_name: string; error: string }[];
  project_count: number;
  fetched_at: string;
}

export interface FleetUtilization {
  clusters: Record<string, { cpu: number | null; memory: number | null; nodes?: number; at?: string | null; error?: string }>;
  fetched_at: string;
}

export interface MetricNode {
  key: string;
  id: string;
  host: string;
  label: string;
  role: string;
  type_name: string;
}

export type MetricRow = { time: string } & Record<string, number | null | string>;

export interface ClusterMetrics {
  cluster_name: string;
  project_id: string;
  period: MetricPeriod;
  granularity: string;
  paused: boolean;
  nodes: MetricNode[];
  series: { cpu: MetricRow[]; memory: MetricRow[]; connections: MetricRow[]; disk: MetricRow[] };
  latest: { cpu?: number | null; memory?: number | null; connections?: number | null; disk?: number | null };
  notes: string[];
}

export interface OperationTarget {
  project_id: string;
  project_name: string | null;
  cluster_name: string;
  status: TargetStatus;
  message: string | null;
  state: string | null;
  started_at: string | null;
  completed_at: string | null;
  duration_seconds?: number | null;
}

export interface AtlasOperation {
  id: number;
  action: PowerAction;
  trigger: "manual" | "scheduled" | "run_now";
  schedule_id: number | null;
  schedule_name: string | null;
  status: OperationStatus;
  targets: OperationTarget[];
  reason: string | null;
  requested_by: string;
  requested_at: string;
  completed_at: string | null;
  duration_seconds: number | null;
  error_message: string | null;
}

export interface ScheduleTarget {
  project_id: string;
  project_name?: string | null;
  cluster_name: string;
}

export interface AtlasSchedule {
  id: number;
  name: string;
  description: string | null;
  targets: ScheduleTarget[];
  schedule_type: "recurring" | "one_time";
  timezone: string;
  stop_cron: string | null;
  start_cron: string | null;
  stop_at: string | null;
  start_at: string | null;
  stop_description: string;
  start_description: string;
  next_stop_at: string | null;
  next_start_at: string | null;
  skip_next_stop: boolean;
  skip_next_start: boolean;
  is_enabled: boolean;
  notify_on: NotifyOn;
  notification_emails: string | null;
  remind_minutes_before: number;
  last_stop_run_at: string | null;
  last_start_run_at: string | null;
  last_run_status: OperationStatus | null;
  created_by: string;
  created_at: string;
  updated_by: string | null;
  updated_at: string;
}

export interface ScheduleInput {
  name: string;
  description?: string | null;
  targets: ScheduleTarget[];
  schedule_type: "recurring" | "one_time";
  timezone: string;
  stop_cron?: string | null;
  start_cron?: string | null;
  stop_at?: string | null;
  start_at?: string | null;
  is_enabled?: boolean;
  notify_on: NotifyOn;
  notification_emails?: string | null;
  remind_minutes_before: number;
  acknowledge_production?: boolean;
}

export interface SchedulePreview {
  valid: boolean;
  error: string | null;
  stop_description?: string;
  start_description?: string;
  stop: string[];
  start: string[];
}

export interface DatabaseUser {
  username: string;
  auth_database: string;
  auth_type: string;
  roles: { role_name: string; database_name: string; collection_name: string | null }[];
  scopes: { name: string; type: string }[];
  description: string | null;
  delete_after: string | null;
}

export interface AccessListEntry {
  entry: string;
  type: string;
  comment: string | null;
  delete_after: string | null;
}

export interface AtlasAlert {
  id: string;
  event_type: string | null;
  status: string | null;
  severity: string | null;
  created_at: string | null;
  updated_at: string | null;
  resolved_at: string | null;
  cluster_name: string | null;
  host: string | null;
  replica_set: string | null;
  metric_name: string | null;
  current_value: string | null;
  acknowledged_until: string | null;
  acknowledged_by: string | null;
  acknowledgement_comment: string | null;
}

export interface AtlasEvent {
  id: string;
  created_at: string | null;
  event_type: string | null;
  description: string;
  cluster_name: string | null;
  replica_set: string | null;
  host: string | null;
  actor: string;
  remote_address: string | null;
}

export interface Snapshot {
  id: string;
  created_at: string | null;
  expires_at: string | null;
  status: string | null;
  type: string | null;
  frequency: string | null;
  size_bytes: number | null;
  description: string | null;
  mongod_version: string | null;
  cloud_provider: string | null;
}

export interface AuditEntry {
  id: number;
  timestamp: string;
  user: string;
  action: string;
  resource: string | null;
  status: string;
  ip_address: string | null;
  details: Record<string, unknown>;
}

// ── Keys ─────────────────────────────────────────────────────────────────────

export const atlasKeys = {
  all: ["mongodb-atlas"] as const,
  status: () => [...atlasKeys.all, "status"] as const,
  projects: () => [...atlasKeys.all, "projects"] as const,
  clusters: () => [...atlasKeys.all, "clusters"] as const,
  utilization: () => [...atlasKeys.all, "utilization"] as const,
  cluster: (projectId: string, name: string) => [...atlasKeys.all, "cluster", projectId, name] as const,
  metrics: (projectId: string, name: string, period: MetricPeriod) =>
    [...atlasKeys.all, "metrics", projectId, name, period] as const,
  snapshots: (projectId: string, name: string) => [...atlasKeys.all, "snapshots", projectId, name] as const,
  schedules: () => [...atlasKeys.all, "schedules"] as const,
  operations: () => [...atlasKeys.all, "operations"] as const,
  operation: (id: number) => [...atlasKeys.all, "operation", id] as const,
  users: (projectId: string) => [...atlasKeys.all, "users", projectId] as const,
  accessList: (projectId: string) => [...atlasKeys.all, "access-list", projectId] as const,
  alerts: (projectId: string, status: string) => [...atlasKeys.all, "alerts", projectId, status] as const,
  events: (projectId: string, cluster: string | null, page: number) =>
    [...atlasKeys.all, "events", projectId, cluster ?? "", page] as const,
  audit: () => [...atlasKeys.all, "audit"] as const,
};

// ── Queries ──────────────────────────────────────────────────────────────────

export function useAtlasStatus() {
  return useQuery<AtlasStatus>({
    queryKey: atlasKeys.status(),
    queryFn: async () => (await apiClient.get(`${BASE}/status`)).data,
    staleTime: 60_000,
  });
}

/** Step-by-step network/key check. A success refreshes everything that depends on it. */
export function useConnectionTest() {
  const qc = useQueryClient();
  return useMutation<ConnectionTestResult, unknown, void>({
    mutationFn: async () => (await apiClient.get(`${BASE}/connection-test`)).data,
    onSuccess: (result) => {
      if (result.ok) qc.invalidateQueries({ queryKey: atlasKeys.all });
    },
  });
}

export function useAtlasProjects(enabled = true) {
  return useQuery<AtlasProject[]>({
    queryKey: atlasKeys.projects(),
    queryFn: async () => (await apiClient.get(`${BASE}/projects`)).data.projects,
    staleTime: 5 * 60_000,
    enabled,
  });
}

/** Polls faster while any cluster is mid stop/start, so the grid follows it. */
export function useAtlasClusters(enabled = true) {
  return useQuery<ClusterInventory>({
    queryKey: atlasKeys.clusters(),
    queryFn: async () => (await apiClient.get(`${BASE}/clusters`)).data,
    staleTime: 15_000,
    enabled,
    refetchInterval: (query) => {
      const data = query.state.data as ClusterInventory | undefined;
      const busy = data?.clusters.some((c) => c.operation_in_progress || (c.state && c.state !== "IDLE"));
      return busy ? 20_000 : 120_000;
    },
  });
}

export function useFleetUtilization(enabled = true) {
  return useQuery<FleetUtilization>({
    queryKey: atlasKeys.utilization(),
    queryFn: async () => (await apiClient.get(`${BASE}/utilization`)).data,
    staleTime: 120_000,
    refetchInterval: 300_000,
    enabled,
  });
}

export function useClusterMetrics(projectId: string, name: string, period: MetricPeriod, enabled = true) {
  return useQuery<ClusterMetrics>({
    queryKey: atlasKeys.metrics(projectId, name, period),
    queryFn: async () =>
      (await apiClient.get(`${BASE}/projects/${projectId}/clusters/${encodeURIComponent(name)}/metrics`, { params: { period } }))
        .data,
    staleTime: 60_000,
    refetchInterval: period === "PT1H" ? 60_000 : 300_000,
    enabled,
  });
}

export function useSnapshots(projectId: string, name: string, enabled = true) {
  return useQuery<{ snapshots: Snapshot[]; count: number }>({
    queryKey: atlasKeys.snapshots(projectId, name),
    queryFn: async () =>
      (await apiClient.get(`${BASE}/projects/${projectId}/clusters/${encodeURIComponent(name)}/snapshots`)).data,
    enabled,
  });
}

export function useSchedules() {
  return useQuery<AtlasSchedule[]>({
    queryKey: atlasKeys.schedules(),
    queryFn: async () => (await apiClient.get(`${BASE}/schedules`)).data.schedules,
    staleTime: 30_000,
    refetchInterval: 60_000,
  });
}

export function useSchedulePreview(params: Record<string, string | undefined> | null) {
  return useQuery<SchedulePreview>({
    queryKey: [...atlasKeys.all, "preview", params],
    queryFn: async () => (await apiClient.get(`${BASE}/schedules/preview`, { params })).data,
    enabled: params !== null,
    staleTime: 30_000,
  });
}

export function useOperations() {
  return useQuery<{ operations: AtlasOperation[]; count: number; in_progress: number }>({
    queryKey: atlasKeys.operations(),
    queryFn: async () => (await apiClient.get(`${BASE}/operations`)).data,
    refetchInterval: (query) => {
      const data = query.state.data as { in_progress: number } | undefined;
      return data && data.in_progress > 0 ? 15_000 : 60_000;
    },
  });
}

/** One operation, polled until it reaches a final status. */
export function useOperation(id: number | null) {
  return useQuery<AtlasOperation>({
    queryKey: atlasKeys.operation(id ?? 0),
    queryFn: async () => (await apiClient.get(`${BASE}/operations/${id}`)).data,
    enabled: id !== null,
    refetchInterval: (query) => ((query.state.data as AtlasOperation | undefined)?.status === "in_progress" ? 10_000 : false),
  });
}

export function useDatabaseUsers(projectId: string | null) {
  return useQuery<{ users: DatabaseUser[]; count: number }>({
    queryKey: atlasKeys.users(projectId ?? ""),
    queryFn: async () => (await apiClient.get(`${BASE}/projects/${projectId}/database-users`)).data,
    enabled: Boolean(projectId),
  });
}

export function useAccessList(projectId: string | null) {
  return useQuery<{ entries: AccessListEntry[]; count: number }>({
    queryKey: atlasKeys.accessList(projectId ?? ""),
    queryFn: async () => (await apiClient.get(`${BASE}/projects/${projectId}/access-list`)).data,
    enabled: Boolean(projectId),
  });
}

export function useAlerts(projectId: string | null, status: "OPEN" | "TRACKING" | "CLOSED") {
  return useQuery<{ alerts: AtlasAlert[]; count: number }>({
    queryKey: atlasKeys.alerts(projectId ?? "", status),
    queryFn: async () => (await apiClient.get(`${BASE}/projects/${projectId}/alerts`, { params: { status } })).data,
    enabled: Boolean(projectId),
  });
}

export function useEvents(projectId: string | null, clusterName: string | null, page: number, pageSize = 100) {
  return useQuery<{ events: AtlasEvent[]; total: number | null; page: number; page_size: number }>({
    queryKey: atlasKeys.events(projectId ?? "", clusterName, page),
    queryFn: async () =>
      (
        await apiClient.get(`${BASE}/projects/${projectId}/events`, {
          params: { page, page_size: pageSize, ...(clusterName ? { cluster_name: clusterName } : {}) },
        })
      ).data,
    enabled: Boolean(projectId),
  });
}

export function useAtlasAudit() {
  return useQuery<{ entries: AuditEntry[]; count: number }>({
    queryKey: atlasKeys.audit(),
    queryFn: async () => (await apiClient.get(`${BASE}/audit`)).data,
    staleTime: 30_000,
  });
}

// ── Mutations ────────────────────────────────────────────────────────────────

function useInvalidate() {
  const qc = useQueryClient();
  return (...keys: ReadonlyArray<readonly unknown[]>) => {
    keys.forEach((key) => qc.invalidateQueries({ queryKey: key }));
    qc.invalidateQueries({ queryKey: atlasKeys.audit() });
  };
}

export interface PowerInput {
  projectId: string;
  clusterName: string;
  action: PowerAction;
  confirm_name?: string;
  reason?: string;
  notify: boolean;
  notification_emails?: string;
}

export function usePowerCluster() {
  const invalidate = useInvalidate();
  return useMutation<AtlasOperation, unknown, PowerInput>({
    mutationFn: async ({ projectId, clusterName, action, ...body }) =>
      (await apiClient.post(`${BASE}/projects/${projectId}/clusters/${encodeURIComponent(clusterName)}/${action}`, body)).data,
    onSuccess: () => invalidate(atlasKeys.clusters(), atlasKeys.operations()),
  });
}

export function useChangeTier() {
  const invalidate = useInvalidate();
  return useMutation<AtlasCluster, unknown, { projectId: string; clusterName: string; instance_size: string; confirm_name?: string; reason?: string }>({
    mutationFn: async ({ projectId, clusterName, ...body }) =>
      (await apiClient.patch(`${BASE}/projects/${projectId}/clusters/${encodeURIComponent(clusterName)}/tier`, body)).data,
    onSuccess: () => invalidate(atlasKeys.clusters()),
  });
}

export function useTestFailover() {
  const invalidate = useInvalidate();
  return useMutation<unknown, unknown, { projectId: string; clusterName: string; confirm_name?: string; reason?: string }>({
    mutationFn: async ({ projectId, clusterName, ...body }) =>
      (await apiClient.post(`${BASE}/projects/${projectId}/clusters/${encodeURIComponent(clusterName)}/test-failover`, body)).data,
    onSuccess: () => invalidate(atlasKeys.clusters()),
  });
}

export function useTakeSnapshot() {
  const invalidate = useInvalidate();
  return useMutation<Snapshot, unknown, { projectId: string; clusterName: string; description: string; retention_days: number }>({
    mutationFn: async ({ projectId, clusterName, ...body }) =>
      (await apiClient.post(`${BASE}/projects/${projectId}/clusters/${encodeURIComponent(clusterName)}/snapshots`, body)).data,
    onSuccess: (_d, v) => invalidate(atlasKeys.snapshots(v.projectId, v.clusterName)),
  });
}

export function useSaveSchedule() {
  const invalidate = useInvalidate();
  return useMutation<AtlasSchedule, unknown, { id?: number; input: Partial<ScheduleInput> }>({
    mutationFn: async ({ id, input }) =>
      id ? (await apiClient.put(`${BASE}/schedules/${id}`, input)).data : (await apiClient.post(`${BASE}/schedules`, input)).data,
    onSuccess: () => invalidate(atlasKeys.schedules(), atlasKeys.clusters()),
  });
}

export function useDeleteSchedule() {
  const invalidate = useInvalidate();
  return useMutation<unknown, unknown, number>({
    mutationFn: async (id) => (await apiClient.delete(`${BASE}/schedules/${id}`)).data,
    onSuccess: () => invalidate(atlasKeys.schedules(), atlasKeys.clusters()),
  });
}

export function useSkipScheduleLeg() {
  const invalidate = useInvalidate();
  return useMutation<AtlasSchedule, unknown, { id: number; leg: Leg; skip: boolean }>({
    mutationFn: async ({ id, ...body }) => (await apiClient.post(`${BASE}/schedules/${id}/skip`, body)).data,
    onSuccess: () => invalidate(atlasKeys.schedules()),
  });
}

export function useRunScheduleLeg() {
  const invalidate = useInvalidate();
  return useMutation<AtlasOperation, unknown, { id: number; leg: Leg }>({
    mutationFn: async ({ id, leg }) => (await apiClient.post(`${BASE}/schedules/${id}/run`, { leg })).data,
    onSuccess: () => invalidate(atlasKeys.operations(), atlasKeys.clusters()),
  });
}

export interface DatabaseUserInput {
  username: string;
  password?: string | null;
  roles: { role_name: string; database_name: string; collection_name?: string | null }[];
  scopes?: { name: string; type: "CLUSTER" }[];
  description?: string | null;
  delete_after_date?: string | null;
}

/** The result carries a generated password once; the caller shows it and forgets it. */
export function useCreateDatabaseUser(projectId: string) {
  const invalidate = useInvalidate();
  return useMutation<{ user: DatabaseUser; password: string | null; password_generated: boolean }, unknown, DatabaseUserInput>({
    mutationFn: async (body) => (await apiClient.post(`${BASE}/projects/${projectId}/database-users`, body)).data,
    onSuccess: () => invalidate(atlasKeys.users(projectId)),
  });
}

export function useUpdateDatabaseUser(projectId: string) {
  const invalidate = useInvalidate();
  return useMutation<
    { user: DatabaseUser; password: string | null },
    unknown,
    { username: string; auth_database: string; roles?: DatabaseUserInput["roles"]; reset_password?: boolean }
  >({
    mutationFn: async ({ username, auth_database, ...body }) =>
      (
        await apiClient.patch(`${BASE}/projects/${projectId}/database-users/${encodeURIComponent(username)}`, body, {
          params: { auth_database },
        })
      ).data,
    onSuccess: () => invalidate(atlasKeys.users(projectId)),
  });
}

export function useDeleteDatabaseUser(projectId: string) {
  const invalidate = useInvalidate();
  return useMutation<unknown, unknown, { username: string; auth_database: string }>({
    mutationFn: async ({ username, auth_database }) =>
      (
        await apiClient.delete(`${BASE}/projects/${projectId}/database-users/${encodeURIComponent(username)}`, {
          params: { auth_database },
        })
      ).data,
    onSuccess: () => invalidate(atlasKeys.users(projectId)),
  });
}

export function useAddAccessListEntry(projectId: string) {
  const invalidate = useInvalidate();
  return useMutation<unknown, unknown, { entry: string; comment?: string | null; delete_after_date?: string | null }>({
    mutationFn: async (body) => (await apiClient.post(`${BASE}/projects/${projectId}/access-list`, body)).data,
    onSuccess: () => invalidate(atlasKeys.accessList(projectId)),
  });
}

export function useDeleteAccessListEntry(projectId: string) {
  const invalidate = useInvalidate();
  return useMutation<unknown, unknown, string>({
    // The entry is a path tail on purpose: "10.0.0.0/24" stays readable in the audit trail.
    mutationFn: async (entry) => (await apiClient.delete(`${BASE}/projects/${projectId}/access-list/${entry}`)).data,
    onSuccess: () => invalidate(atlasKeys.accessList(projectId)),
  });
}

export function useAcknowledgeAlert(projectId: string) {
  const invalidate = useInvalidate();
  return useMutation<AtlasAlert, unknown, { alertId: string; acknowledged_until?: string | null; comment?: string; unacknowledge?: boolean }>({
    mutationFn: async ({ alertId, ...body }) =>
      (await apiClient.post(`${BASE}/projects/${projectId}/alerts/${alertId}/acknowledge`, body)).data,
    onSuccess: () => invalidate([...atlasKeys.all, "alerts", projectId]),
  });
}
